import{_ as n,C as c,o as l,c as h,j as d,a as e,E as o,a5 as r}from"./chunks/framework.BYIUCCsM.js";const P=JSON.parse('{"title":"动态录入","description":"","frontmatter":{},"headers":[],"relativePath":"components/dynamic-input.md","filePath":"components/dynamic-input.md","lastUpdated":1787407517000}'),m={name:"components/dynamic-input.md"},u={id:"动态录入",tabindex:"-1"};function p(s,t,b,g,x,y){const i=c("Badge"),a=c("XhDemo");return l(),h("div",null,[d("h1",u,[t[0]||(t[0]=e("动态录入 ",-1)),o(i,{type:"info",text:"dynamic-input"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#动态录入","aria-label":'Permalink to "动态录入 <Badge type="info" text="dynamic-input" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一组行数可变的录入行：可以加一行、删一行、换顺序。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>联系方式、规格参数、收件人这类&quot;数量由用户决定&quot;的重复字段。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>行数固定：直接写几行。</li><li>每一行是一个短词：用<a href="./tags-input">标签输入</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>min</code> / <code>max</code> 约束行数，到下限时删除按钮不可用。</li><li><code>movable</code> 给出上移下移。</li><li><code>createItem</code> 决定新增一行时的初值。</li><li>一行里可以放多个字段。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>加一行、删一行归组件管；行里放什么控件归作者，写在 item-content 里</p>',10)),o(a,{src:"dynamic-input/01-basic"}),t[4]||(t[4]=d("h3",{id:"行数上下限",tabindex:"-1"},[e("行数上下限 "),d("a",{class:"header-anchor",href:"#行数上下限","aria-label":'Permalink to "行数上下限"'},"​")],-1)),t[5]||(t[5]=d("p",null,"到 min 删除把手按不动、到 max 新增把手按不动；两者都转 aria-disabled，焦点留得住",-1)),o(a,{src:"dynamic-input/02-min-max"}),t[6]||(t[6]=d("h3",{id:"换序",tabindex:"-1"},[e("换序 "),d("a",{class:"header-anchor",href:"#换序","aria-label":'Permalink to "换序"'},"​")],-1)),t[7]||(t[7]=d("p",null,"movable 开了才出上下把手；挪完焦点跟着这一行走，键盘可以连按一路挪到底",-1)),o(a,{src:"dynamic-input/03-movable"}),t[8]||(t[8]=d("h3",{id:"一行多个字段",tabindex:"-1"},[e("一行多个字段 "),d("a",{class:"header-anchor",href:"#一行多个字段","aria-label":'Permalink to "一行多个字段"'},"​")],-1)),t[9]||(t[9]=d("p",null,"行数据是对象，createItem 造一个空项；改字段时整份重建数组，行号不跟着变",-1)),o(a,{src:"dynamic-input/04-object-rows"}),t[10]||(t[10]=d("h3",{id:"禁用与程序化操作",tabindex:"-1"},[e("禁用与程序化操作 "),d("a",{class:"header-anchor",href:"#禁用与程序化操作","aria-label":'Permalink to "禁用与程序化操作"'},"​")],-1)),t[11]||(t[11]=d("p",null,"禁用时三类把手全按不动；从外面加一条走同一条闸门，整份替换值则不受闸门约束",-1)),o(a,{src:"dynamic-input/05-disabled-and-api"}),t[12]||(t[12]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-dynamic-input&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhDynamicInputAddTrigger</code> <code>XhDynamicInputItem</code> <code>XhDynamicInputItemAction</code> <code>XhDynamicInputItemContent</code> <code>XhDynamicInputItemDeleteTrigger</code> <code>XhDynamicInputMoveDownTrigger</code> <code>XhDynamicInputMoveUpTrigger</code> <code>XhDynamicInputRoot</code></td></tr><tr><td>组合式函数</td><td><code>useDynamicInput</code></td></tr><tr><td>状态机</td><td><code>dynamicInputMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/dynamic-input.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;dynamic-input&quot;</code>：<strong><code>root</code></strong> · <code>item</code> · <code>item-content</code> · <code>item-action</code> · <code>add-trigger</code> · <code>item-delete-trigger</code> · <code>move-up-trigger</code> · <code>move-down-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>unknown[]</code></td><td></td><td>受控数据数组；给了就由宿主说了算，机器不自改，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>unknown[]</code></td><td></td><td>非受控初始数据数组。</td></tr><tr><td><code>min</code></td><td><code>number</code></td><td></td><td>最少几行。到了这个数，删除把手就按不动了。缺省 0。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td><td>最多几行。到了这个数，新增把手就按不动了。缺省不限。</td></tr><tr><td><code>createItem</code></td><td><code>() =&gt; unknown</code></td><td></td><td>新增一行时造一个空项。不给就插一个 null。</td></tr><tr><td><code>movable</code></td><td><code>boolean</code></td><td></td><td>出不出换序把手。关（默认）时两个换序把手一律收起。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：新增、删除、换序三路都按不动。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;DynamicInputTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: DynamicInputValueChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>DynamicInputValueChangeDetails</code></td><td>数据数组变化；detail 为 <code>{ value: unknown[] }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhDynamicInputRoot</code></td><td><code>default</code></td><td><code>DynamicInputRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.ADD</code> · <code>ITEM.REMOVE</code> · <code>ITEM.MOVE</code></p><p><strong>判据</strong>：<code>canAdd</code> · <code>canRemove</code> · <code>canMove</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useDynamicInput</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>unknown[]</code></td><td></td></tr><tr><td><code>items</code></td><td><code>DynamicInputItem[]</code></td><td>逐行的读侧投影，含渲染用的 key。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>movable</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>atMin</code></td><td><code>boolean</code></td><td>已到下限：再删就少于 min 了。</td></tr><tr><td><code>atMax</code></td><td><code>boolean</code></td><td>已到上限：再加就多于 max 了。</td></tr><tr><td><code>canAdd</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: unknown[]) =&gt; void</code></td><td>整份替换，不受 min / max 约束。</td></tr><tr><td><code>add</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>remove</code></td><td><code>(index: number) =&gt; void</code></td><td></td></tr><tr><td><code>move</code></td><td><code>(from: number, to: number) =&gt; void</code></td><td></td></tr><tr><td><code>moveUp</code></td><td><code>(index: number) =&gt; void</code></td><td></td></tr><tr><td><code>moveDown</code></td><td><code>(index: number) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(item: DynamicInputItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemContentProps</code></td><td><code>(item: DynamicInputItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemActionProps</code></td><td><code>(item: DynamicInputItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getAddTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getItemDeleteTriggerProps</code></td><td><code>(item: DynamicInputItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getMoveUpTriggerProps</code></td><td><code>(item: DynamicInputItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getMoveDownTriggerProps</code></td><td><code>(item: DynamicInputItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>add-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>item-delete-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>item-delete-trigger</code></td><td><code>aria-label</code></td><td>label.deleteItem(item.index + 1, count)</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/dynamic-input.css</code> 按部件选择：<code>[data-scope=&quot;dynamic-input&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-at-max</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-at-min</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-movable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-first</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-last</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>add-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-delete-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-dynamic-input-action-gap</code> · <code>--xh-dynamic-input-add-bg</code> · <code>--xh-dynamic-input-add-bg-active</code> · <code>--xh-dynamic-input-add-bg-hover</code> · <code>--xh-dynamic-input-add-border</code> · <code>--xh-dynamic-input-add-border-disabled</code> · <code>--xh-dynamic-input-add-border-hover</code> · <code>--xh-dynamic-input-add-fg</code> · <code>--xh-dynamic-input-add-font-size</code> · <code>--xh-dynamic-input-add-height</code> · <code>--xh-dynamic-input-add-px</code> · <code>--xh-dynamic-input-add-radius</code> · <code>--xh-dynamic-input-content-gap</code> · <code>--xh-dynamic-input-gap</code> · <code>--xh-dynamic-input-icon-size</code> · <code>--xh-dynamic-input-item-delete-fg-hover</code> · <code>--xh-dynamic-input-item-gap</code> · <code>--xh-dynamic-input-item-padding</code> · <code>--xh-dynamic-input-item-radius</code> · <code>--xh-dynamic-input-trigger-bg</code> · <code>--xh-dynamic-input-trigger-bg-active</code> · <code>--xh-dynamic-input-trigger-bg-hover</code> · <code>--xh-dynamic-input-trigger-fg</code> · <code>--xh-dynamic-input-trigger-fg-hover</code> · <code>--xh-dynamic-input-trigger-font-size</code> · <code>--xh-dynamic-input-trigger-radius</code> · <code>--xh-dynamic-input-trigger-size</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>每行里放<a href="./field">表单字段</a>与各类录入组件；整体放进<a href="./form">表单</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>新增一行后把焦点移到这一行的第一个输入框。</li><li>删除按钮要说明删的是哪一行（<code>aria-label</code> 带上行号或内容）。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>删除不给撤销，误删只能重填。</li><li>行数上限只在提交时才提示。</li></ul>',46))])}const q=n(m,[["render",p]]);export{P as __pageData,q as default};
